1. 검색 API 엔드포인트 구현:
   - GET /api/memos/search?q=keyword&category=id&from=date&to=date
2. 데이터베이스 검색 쿼리 최적화:
```typescript
async function searchMemos(userId: string, params: SearchParams) {
  const { q, category, from, to, page = 1, limit = 10 } = params;

  const where: any = { userId };

  if (q) {
    where.OR = [
      { title: { contains: q, mode: 'insensitive' } },
      { content: { contains: q, mode: 'insensitive' } },
      { summary: { contains: q, mode: 'insensitive' } }
    ];
  }

  if (category) {
    where.categoryId = category;
  }

  if (from || to) {
    where.createdAt = {};
    if (from) where.createdAt.gte = new Date(from);
    if (to) where.createdAt.lte = new Date(to);
  }

  const skip = (page - 1) * limit;

  const [memos, total] = await Promise.all([
    prisma.memo.findMany({
      where,
      include: { category: true },
      orderBy: { createdAt: 'desc' },
      skip,
      take: limit
    }),
    prisma.memo.count({ where })
  ]);

  return { memos, total, page, limit };
}
```
